// Pronunciation playback: prefer pre-rendered neural MP3s (generated by
// scripts/generate_audio.py via edge-tts), and transparently fall back to the
// browser's Web Speech API when a file is missing or can't play.

import type { AudioManifest } from '@/types'
import { speak, stopSpeaking } from './tts'
import { clipId, textHash } from './textHash'

const base = import.meta.env.BASE_URL

// Active audio context, kept module-global because only one pack is active at a
// time. The data store sets the language + available voices; the settings store
// pushes the user's chosen voice key.
let currentCode = 'en'
let availableVoiceKeys: string[] = []
let defaultVoiceKey: string | null = null
let selectedVoiceKey: string | null = null

export function setAudioLang(code: string): void {
  currentCode = code
}

export function setAudioVoices(voiceKeys: string[], defaultKey: string | null): void {
  availableVoiceKeys = voiceKeys
  defaultVoiceKey = defaultKey
}

export function setAudioVoiceKey(key: string | null): void {
  selectedVoiceKey = key
}

/** The voice folder to use, honouring the user's choice then the default. */
function effectiveVoice(): string | null {
  if (selectedVoiceKey && availableVoiceKeys.includes(selectedVoiceKey)) return selectedVoiceKey
  if (defaultVoiceKey && availableVoiceKeys.includes(defaultVoiceKey)) return defaultVoiceKey
  return availableVoiceKeys[0] ?? null
}

/** Fetch the per-language audio voice manifest (null if none was generated). */
export async function loadAudioManifest(code: string): Promise<AudioManifest | null> {
  try {
    const res = await fetch(`${base}audio/${code}/index.json`)
    if (!res.ok) return null
    return (await res.json()) as AudioManifest
  } catch {
    return null
  }
}

/** URL of the pre-rendered audio for a headword ('' when no audio exists). */
export function wordAudio(id: number): string {
  const v = effectiveVoice()
  return v ? `${base}audio/${currentCode}/${v}/w${id}.mp3` : ''
}

/**
 * URL of the pre-rendered audio for an example sentence ('' when none).
 * Pass the sentence text: the URL then carries its fingerprint, so a rewritten
 * sentence never plays a stale cached clip (see textHash).
 */
export function exampleAudio(id: number, text?: string): string {
  const v = effectiveVoice()
  if (!v) return ''
  const url = `${base}audio/${currentCode}/${v}/e${id}.mp3`
  return text ? `${url}?v=${textHash(text)}` : url
}

/**
 * URL of a recorded sentence that is not a word's own example: collocations,
 * grammar examples, story lines ('' when the pack has no recorded voices).
 * These clips live only in R2, named after the text itself, so a rewritten
 * sentence simply gets a new clip; until one is recorded the request 404s and
 * pronounce() reads the text with the browser's voice instead.
 */
export function textAudio(text: string): string {
  const v = effectiveVoice()
  return v ? `${base}audio/${currentCode}/${v}/t/${clipId(text)}.mp3` : ''
}

/** URL of the recorded audio for an everyday phrase ('' when none). */
export function phraseAudio(id: number, text?: string): string {
  const v = effectiveVoice()
  if (!v) return ''
  const url = `${base}audio/${currentCode}/${v}/p${id}.mp3`
  return text ? `${url}?v=${textHash(text)}` : url
}

// Clips already pulled into the HTTP cache this session, so a learner tapping
// back and forth doesn't re-issue requests.
const prefetched = new Set<string>()
// Clips the server does not have (yet): played with the browser's voice
// straight away instead of after a round trip that ends in a 404.
const missing = new Set<string>()
// A ready <audio> per prefetched clip. A fresh element still has to load and
// decode the cached file (110–130 ms on a slow phone); a ready one starts in a
// couple of milliseconds. Bounded, oldest dropped first.
const ready = new Map<string, HTMLAudioElement>()
const READY_MAX = 24

function keepReady(url: string, audio: HTMLAudioElement): void {
  ready.delete(url)
  ready.set(url, audio)
  while (ready.size > READY_MAX) ready.delete(ready.keys().next().value!)
}

/** The learner asked the browser to save data: don't fetch ahead of a tap. */
function savingData(): boolean {
  if (typeof navigator === 'undefined') return false
  return !!(navigator as Navigator & { connection?: { saveData?: boolean } }).connection?.saveData
}

/**
 * Warm the clips that are about to be needed: into the HTTP cache (iOS Safari
 * ignores preload) and into a ready <audio> element. Without this the first
 * tap on a speaker pays a full round trip — 1–2 s on mobile data. Failures are
 * ignored: playback still falls back to Web Speech on its own.
 */
export function prefetchAudio(urls: (string | undefined | null)[]): void {
  if (savingData()) return
  for (const url of urls) {
    if (!url || prefetched.has(url)) continue
    prefetched.add(url)
    void fetch(url, { cache: 'force-cache' })
      .then((res) => {
        if (res.status === 404) return void missing.add(url)
        if (!res.ok || typeof Audio === 'undefined') return
        const audio = new Audio(url)
        audio.preload = 'auto'
        keepReady(url, audio)
      })
      .catch(() => {})
  }
}

let current: HTMLAudioElement | null = null

function clampRate(rate: number): number {
  return Math.max(0.5, Math.min(1.5, rate))
}

/** Stop any in-flight pronunciation (audio file or speech). */
export function stopPronounce(): void {
  if (current) {
    current.pause()
    current = null
  }
  stopSpeaking()
}

export interface PronounceOptions {
  /** Pre-rendered audio URL to try first. */
  audioSrc?: string
  /** Text used for the Web Speech fallback. */
  text: string
  /** BCP-47 language for the fallback voice. */
  lang: string
  rate?: number
  onStart?: () => void
  onEnd?: () => void
}

/**
 * Play a word/sentence. Tries the MP3 first; on any load/play error falls back
 * to Web Speech. Cancels any previous playback so rapid taps don't overlap.
 */
export function pronounce(opts: PronounceOptions): void {
  stopPronounce()
  const { audioSrc, text, lang, rate = 1, onStart, onEnd } = opts

  if (!audioSrc || missing.has(audioSrc)) {
    speak(text, { lang, rate, onStart, onEnd })
    return
  }

  // A ready element is reused, and handed back once this play is over so a
  // second tap is just as quick.
  const warm = ready.get(audioSrc)
  ready.delete(audioSrc)
  const audio = warm ?? new Audio(audioSrc)
  if (warm) audio.currentTime = 0
  audio.playbackRate = clampRate(rate)
  current = audio

  let settled = false // guards against double-handling (error + play().catch)
  const done = () => {
    audio.removeEventListener('playing', onPlaying)
    audio.removeEventListener('ended', onEnded)
    audio.removeEventListener('error', fallback)
  }
  const fallback = () => {
    if (settled) return
    settled = true
    done()
    if (current === audio) current = null
    speak(text, { lang, rate, onStart, onEnd })
  }
  const onPlaying = () => {
    if (settled) return
    settled = true
    onStart?.()
  }
  const onEnded = () => {
    done()
    if (current === audio) current = null
    keepReady(audioSrc, audio)
    onEnd?.()
  }

  audio.addEventListener('playing', onPlaying)
  audio.addEventListener('ended', onEnded)
  audio.addEventListener('error', fallback)
  audio.play().catch(fallback)
}
